"""Build docs/final_numbers_v7.md: best method per property, every pure-compound number read from committed CSVs."""
import sys
sys.path.insert(0, "src")
from pathlib import Path
import pandas as pd
from fuelblend.api import best_methods as BM

R = Path(__file__).resolve().parents[3]
rf = pd.read_csv(R / BM.RF_SRC[0]).set_index("target")
dm = pd.read_csv(R / BM.DM_SRC[0]).set_index("target")
bl = pd.read_csv(R / "results/v7/final/blend_from_pure/summary.csv").set_index("task")
L = ["# v7 final numbers: best method per property", "",
     "Generated by `scripts/v7/final/build_final_numbers_v7.py`. Every number is read from a committed CSV named in the table notes. "
     "All errors are scaffold 5-fold CV on dev rows that were also used for tuning, so they are optimistic. Locked sets were not spent. "
     "The v5 numbers in `docs/final_numbers_v5.md` are unchanged and remain the source for blend properties.", "",
     "## A. Pure compounds (deployed in `fuelblend.api.predict_pure`)", "",
     "| property | n | unit | constant MAE | random forest MAE | D-MPNN (long cap) MAE | deployed | evidence MAE | reading |",
     "|---|---|---|---|---|---|---|---|---|"]
for p, e in BM.PURE.items():
    L.append(f"| {p} | {e.n} | {e.unit} | {dm.loc[p,'mae_const']:.4g} | {rf.loc[p,'mae_rf']:.4g} | {dm.loc[p,'mae_long']:.4g} | "
             f"{'random forest' if e.method=='rf_rdkit2d' else 'D-MPNN'} | {BM.evidence_mae(p):.4g} | {e.significance} |")
L += ["", f"Sources: `{BM.RF_SRC[0]}` (random forest), `{BM.DM_SRC[0]}` (constant and D-MPNN), paired bootstrap in "
      "`results/v7/track_b/curves_v1_long/long_vs_trees.csv`. The deployed D-MPNN is one fixed configuration (hidden 200, depth 4, dropout 0.1, "
      "1000-epoch cap, patience 100, five-model ensemble). The nested-HPO D-MPNN of Task 10 scored slightly lower on density, melting point and YSI "
      "(`docs/v7_errors_by_property.md`) but used a different parameter set per fold, so no single deployable configuration corresponds to it.",
      "", "## B. Blend properties (designated route stays v5)", "",
      "| property | designated method | v7 best alternative | why not adopted |", "|---|---|---|---|"]
for k, d in BM.BLEND.items():
    L.append(f"| {k} | {d['method']} | {d['v7_candidate']} | {d['why_not']} |")
L += ["", "Full per-method error tables for blends, oxygenates, equation parameters and conformal coverage: `docs/v7_errors_by_property.md`; "
      "complete task-by-task results: `docs/v7_results_table.md`.", "",
      "## C. Exploratory blend values from the pure models (in `predict_fuel`)", "",
      "| key | task | systems | rows | MAE model | MAE constant | reading |", "|---|---|---|---|---|---|---|"] + [
      f"| {k} | {t} | {int(bl.loc[t].n_systems)} | {int(bl.loc[t].n_rows)} | {bl.loc[t].mae_model:.4g} | {bl.loc[t].mae_const:.4g} | "
      f"{'usable, exploratory' if bl.loc[t].usable_exploratory else 'no skill shown'} |"
      for k, t in (("dcn_blend_exploratory", "dcn_leenhouts"), ("ron_blend_exploratory", "ron_kaust"),
                   ("mon_blend_exploratory (not offered, sources disagree): Leenhouts", "mon_leenhouts"), ("same, KAUST", "mon_kaust"))] + [
      "", "Linear mole-fraction rule, no mixture fitting; source `results/v7/final/blend_from_pure/summary.csv`, reading in `READING.md`. "
      "Uncertified: no conformal margin, no lab validation; RON rests on 5 systems. Cetane has no mixture data.",
      "", "## D. Limits", "",
      "* Real-fuel freezing point: status: no skill shown. Cold viscosity: status: no skill shown.",
      "* Pure-compound predictions carry no conformal margin; the MAE is a dev-row CV estimate, not a certified bound.",
      "* Un-refit Antoine constants are not evaluated for C10+ alkanes (trap 3); Antoine constants predicted by parameter heads are not used for flash.",
      "* The fresh external-lock flash set (HANNA vs UNIFAC) remains unspent.",
      "* No laboratory validation exists; certification is model-level only."]
(R / "docs/final_numbers_v7.md").write_text("\n".join(L) + "\n", encoding="utf-8")
print("written")
